@RestController
class OrderController {
    private final OrderRepository orders;
    private final BillingRepository billing;

    void confirm(long id) {
        Order o = orders.findById(id);
        o.setStatus("PAID");
        billing.markInvoicePaid(id);   // billing rule, written here
        orders.save(o);
    }
}

package com.shop.payments;

import com.shop.orders.internal.OrderRow;
import com.shop.orders.internal.OrderJdbcDao;

class PaymentService {
    private final OrderJdbcDao orderDao;

    void pay(long orderId) {
        OrderRow row = orderDao.selectForUpdate(orderId);
        row.status = "PAID";
        orderDao.update(row);
    }
}

// module: orders
ordersJdbc.update("update orders set status = 'PAID' where id = ?", id);

// module: payments  (different module, same table)
paymentsJdbc.update("update orders set status = 'PAID' where id = ?", id);

A: one shop.jar; packages controller/ service/ repository/;
   OrderService and BillingService share the orders and invoices tables

B: one shop.jar; modules orders/ payments/ inventory/;
   each module owns its tables, others call its public API only

C: 4 services, 4 pipelines, released together with one version tag;
   payments writes the orders table directly

